// ---------------------------------------------------------------------------------------------
/** Approximation of libslic3r elephant_foot_compensation(): shrink but keep thin features. */
function elephantFootCompensation(exs, efc, minWidth) {
  const out = [];
  for (const e of exs) {
    const shr = offsetEx([e], -efc * SCALE, JT.miter);
    const a0 = exArea(e), a1 = exsArea(shr);
    if (!shr.length || a1 < 0.05 * a0) {
      // too thin: compensate less so that at least the external perimeter fits
      const maybe = offsetEx([e], -Math.max(0, Math.min(efc, 0.25 * minWidth)) * SCALE, JT.miter);
      out.push(...(maybe.length ? maybe : [e]));
    } else out.push(...shr);
  }
  return out;
}

// ---------------------------------------------------------------------------------------------
/**
 * Arachne-like perimeter generation.
 * Volume model: walls fill the band between the (slightly inset) contour and the inner contour
 * offset by the full wall depth; thin parts are filled entirely (variable width beads).
 */
function generatePerimeters(slices, layer, reg, cfg, fl) {
  const paths = [];
  const fillAreas = [];
  const fillAreasTB = [];
  let loops = cfg.num('wall_loops');
  if (!(loops >= 0)) loops = 2;
  const extW = fl.external.width, extS = fl.external.spacing;
  const perS = fl.perimeter.spacing;
  const solidS = fl.solid.spacing;
  const h = layer.height;
  const onlyOneWallTop = toBool(cfg.get('only_one_wall_top'));
  const onlyOneWallFirst = toBool(cfg.get('only_one_wall_first_layer'));
  const infillOverlap = cfg.get('infill_wall_overlap');
  const tbOverlap = cfg.get('top_bottom_infill_wall_overlap');
  const minFeature = toNum(cfg.get('min_feature_size'), fl.nozzle) || 0.1;
  const topmost = !layer.upper;
  const bottommost = !layer.lower;
  const resolution = (cfg.num('resolution') || 0.012) * SCALE;
  const upperGrown = (!topmost && onlyOneWallTop && loops > 1)
    ? offset(layer.upper.lslices, Math.max(extS / 2, toNum(cfg.get('min_width_top_surface'), fl.perimeter.width) || 3 * fl.perimeter.width) * SCALE)
    : null;

  for (const island of slices) {
    let nLoops = loops;
    if (layer.id === 0 && onlyOneWallFirst) nLoops = Math.min(1, nLoops);
    if (nLoops > 1 && onlyOneWallTop && topmost) nLoops = 1;
    if (nLoops === 0) { fillAreas.push(island); continue; }
    const last = offsetEx([island], -(extW / 2 - extS / 2) * SCALE, JT.miter);
    if (!last.length) continue;
    const widths = [];
    for (let i = 0; i < nLoops; i++) widths.push(i === 0 ? extS : perS);
    // Top split: areas exposed on top (far from the upper layer) only get the outer wall.
    let topArea = null;
    if (upperGrown && nLoops > 1) {
      const exposed = diffEx([island], upperGrown);
      if (exposed.length) topArea = exposed;
    }
    const islandLoops = [];
    let B = last; // current boundary
    let depth = 0;
    for (let i = 0; i < nLoops; i++) {
      const s = widths[i];
      let Bi = B;
      if (i >= 1 && topArea) {
        // inner walls are not generated below exposed top areas
        Bi = diffEx(B, offset(topArea, (extS / 2) * SCALE));
      }
      const C = offsetEx(Bi, -(s / 2) * SCALE, JT.miter);
      for (const ex of C) {
        islandLoops.push({ pts: ex.contour, hole: false, i, s });
        for (const hh of ex.holes) islandLoops.push({ pts: hh, hole: true, i, s });
      }
      depth += s;
      B = offsetEx(last, -depth * SCALE, JT.miter);
      if (i >= 1 && topArea) B = diffEx(B, offset(topArea, (extS / 2) * SCALE));
      if (!B.length) break;
    }
    // inner contour (for infill)
    let inner = offsetEx(last, -depth * SCALE, JT.miter);
    if (topArea && nLoops > 1) {
      const innerTop = intersectionEx(offsetEx(last, -extS * SCALE), offset(topArea, (extS / 2) * SCALE));
      inner = unionEx(inner, innerTop);
      inner = intersectionEx(inner, offsetEx(last, -extS * SCALE));
    }
    // volume bookkeeping: wall area = last - inner
    const wallArea = (exsArea(last) - exsArea(inner)) / (SCALE * SCALE);
    let loopArea = 0;
    for (const l of islandLoops) loopArea += (pathLength(l.pts, true) / SCALE) * l.s;
    const thinPaths = [];
    if (wallArea > loopArea + 0.05 * extS * extS) {
      // residual thin parts not covered by any loop band: arachne fills them with variable width beads
      const bandPolys = [];
      for (const l of islandLoops) {
        const o = offset([l.pts], (l.s / 2) * SCALE, JT.miter);
        const ii = offset([l.pts], -(l.s / 2) * SCALE, JT.miter);
        bandPolys.push(...diff(o, ii));
      }
      const coveredArea = bandPolys.length ? union(bandPolys) : [];
      const resid = diffEx(diffEx(last, exsToPaths(inner)), coveredArea);
      for (const r of resid) {
        const a = exArea(r) / (SCALE * SCALE);
        const per = pathLength(r.contour, true) / SCALE;
        if (a <= 0 || per <= 0) continue;
        const w = (2 * a) / per;
        if (w < minFeature) continue;
        const mid = offsetEx([r], -(w / 2) * SCALE, JT.miter);
        const pts = mid.length ? mid[0].contour : r.contour;
        const hp = halfPath(pts);
        // Arachne drops beads thinner than min_feature_size and tiny fragments
        if (pathLength(hp, false) / SCALE < fl.nozzle) continue;
        thinPaths.push({ pts: hp, vol: a * h, w });
      }
    }
    // scale factor for loop flows so that loop volume matches wall band area
    let thinArea = 0;
    for (const t of thinPaths) thinArea += t.vol / h;
    let k = loopArea > 0 ? (wallArea - thinArea) / loopArea : 1;
    if (!(k > 0)) k = 1;
    k = Math.max(0.5, Math.min(1.5, k));
    // order: inner walls first then outer (wall_sequence inner/outer), per island
    const seq = String(cfg.get('wall_sequence') || 'inner wall/outer wall');
    const sorted = islandLoops.slice().sort((a, b) => (seq.startsWith('outer') ? a.i - b.i : b.i - a.i));
    for (const l of sorted) {
      const isExt = l.i === 0;
      const flow = isExt ? fl.external : fl.perimeter;
      let pts = l.pts;
      // CCW for contours, CW for holes (wall_direction ccw); clipper already returns that
      paths.push({ role: isExt ? 'external' : 'perimeter', pts, closed: true, mm3: flow.mm3PerMm * k * (l.s / (isExt ? extS : perS)), width: flow.width, height: h, loopIndex: l.i, hole: l.hole });
    }
    for (const t of thinPaths) {
      const plen = Math.max(1e-6, pathLength(t.pts, false) / SCALE);
      paths.push({ role: 'external', pts: t.pts, closed: false, mm3: t.vol / plen, width: t.w, height: h, thin: true });
    }
    // infill area
    if (inner.length) {
      const spacing = nLoops === 1 ? extS : perS;
      if (offsetEx(inner, -(spacing / 2) * SCALE).length === 0) inner = [];
    }
    if (inner.length) {
      const inset = nLoops === 1 ? extS : perS;
      const ov = (topmost || bottommost) ? toNum(tbOverlap, inset) : toNum(infillOverlap, inset);
      const minSp = solidS * (1 - INSET_OVERLAP_TOLERANCE) * SCALE;
      const simp = simplifyExs(inner, resolution);
      const fa = offset2Ex(simp, -minSp / 2, (ov || 0) * SCALE + minSp / 2, JT.miter);
      fillAreas.push(...fa);
    }
  }
  // overhang classification for perimeters
  let out = paths;
  if (layer.lower && toBool(cfg.get('detect_overhang_wall'))) {
    out = classifyOverhangs(paths, layer.lower.lslices, fl);
  }
  return { paths: out, fillAreas: unionEx(fillAreas), fillAreasTB };
}

function halfPath(pts) {
  // take the longer half of a closed contour as an open centre-line approximation
  const n = pts.length;
  if (n < 3) return pts.slice();
  let per = 0;
  const cum = [0];
  for (let i = 0; i < n; i++) { const a = pts[i], b = pts[(i + 1) % n]; per += Math.hypot(b.X - a.X, b.Y - a.Y); cum.push(per); }
  const out = [pts[0]];
  for (let i = 1; i < n && cum[i] <= per / 2; i++) out.push(pts[i]);
  return out.length >= 2 ? out : [pts[0], pts[1]];
}
